pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmt, uint256 withdrawAmt) public {
        // Keep amounts within reasonable bounds to avoid overflow on total tracking
        depositAmt = bound(depositAmt, 0, 1e36);
        withdrawAmt = bound(withdrawAmt, 0, 1e36);

        // Setup: fund a fresh account and deposit
        address user = address(0x1000);
        vm.deal(user, depositAmt);
        vm.prank(user);
        c.deposit{value: depositAmt}();

        // Record the invariant's components before withdraw attempt
        uint256 balBefore = user.balance;
        uint256 contractBalBefore = address(c).balance;
        uint256 recordedBalBefore = c.balances(user);

        // Withdraw may succeed or revert depending on the version; we catch the outcome
        bool ok;
        vm.prank(user);
        try c.withdraw(withdrawAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 contractBalAfter = address(c).balance;
        uint256 recordedBalAfter = c.balances(user);

        // For both versions, if the withdrawal succeeded, the user's ETH balance must have increased
        // by exactly the withdrawn amount (no less, no more) AND the contract balance must have decreased
        // by that amount AND the recorded balance must have decreased by that amount.
        // The buggy version removes the require, so it succeeds even when withdrawAmt > recordedBalBefore,
        // leading to an underflow in the recorded balance (making it huge) and taking ETH the user didn't have.
        // Our assertion: if withdrawal succeeded, the contract's ETH + all recorded balances must be at least
        // the total deposited. Here total deposited before withdraw was depositAmt.
        // This invariant holds for the correct contract but breaks for the buggy one when overdraw.

        // The invariant: address(c).balance + all recorded balances >= total ever deposited
        // Since only one user deposited, total ever deposited == depositAmt
        assertTrue(!ok || (contractBalAfter + c.balances(user) >= depositAmt));
    }
}

