pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 withdrawAmount) public {
        vm.assume(amount > 0 && withdrawAmount > 0 && withdrawAmount <= amount);
        vm.deal(address(this), amount);
        c.deposit{value: amount}();
        uint256 balanceBefore = address(c).balance;
        c.withdraw(withdrawAmount);
        // Invariant: total balance tracked internally should match actual contract balance
        // After withdraw, actual balance = balanceBefore - withdrawAmount only if transfer actually sent ether
        // Since contract has no other balances holder, the invariant is balanceBefore - actual balance == sum of individual balances withdrawn
        // We check that sum of balances in the contract (only address(this)) equals the actual ether balance
        // Since only this caller deposited, we check: c.balances(address(this)) == address(c).balance
        // But balances is private mapping; we can't read it directly. We can test indirectly:
        // If withdraw didn't transfer, contract balance still equals deposit, but internal balance decreased.
        // Another deposit by same address would show inconsistency via sum of balances vs total balance.
        // But we need a public surface reading. The contract has no balance getter.
        // We can use another withdraw to detect: if internal balance < actual balance, withdrawing that amount would revert unexpectedly.
        // Better: use refund() - refund sends balances[msg.sender]. If balances decreased but ether wasn't sent, contract balance > total tracked.
        // Let's test that address(this) can refund the remaining balance.
        uint256 contractBalanceAfterWithdraw = address(c).balance;
        // After withdraw, try refund - it should send the remaining internal balance.
        uint256 callerBalanceBeforeRefund = address(this).balance;
        try c.refund() { } catch { }
        uint256 callerBalanceAfterRefund = address(this).balance;
        // The invariant: refund must transfer exactly the internal balance.
        // If internal balance = deposit - withdrawAmount (correct) and actual balance = deposit (because transfer sent 0), then refund sends deposit, not deposit - withdrawAmount.
        // So caller receives more than expected if invariant broken.
        // Specifically: callerBalanceAfterRefund - callerBalanceBeforeRefund should equal withdrawAmount if bug present (contract sent full deposit instead of reduced balance).
        // For correct version: internal balance = deposit - withdrawAmount, actual balance = deposit - withdrawAmount, so refund sends deposit - withdrawAmount.
        // We assert: callerBalanceAfterRefund - callerBalanceBeforeRefund == withdrawAmount is the bug condition.
        // The correct version should NOT satisfy this (unless withdrawAmount == amount).
        // But we need a single assertion that reference satisfies for ALL and bug fails for SOME.
        // Let's assert: callerBalanceAfterRefund - callerBalanceBeforeRefund == 0? No.
        // Better: assert that the contract's ether balance after refund is 0 for correct (refund drains its balance).
        // For bug: after refund, contract still has some ether because it sent full deposit but only decreased internal balance.
        // Actually: bug contract balance before refund = deposit (since transfer(0) didn't move). after refund, it transfers balances[msg.sender] = deposit - withdrawAmount, so contract balance left = deposit - (deposit - withdrawAmount) = withdrawAmount.
        // Correct: contract balance before refund = deposit - withdrawAmount, after refund = 0.
        // So after refund, assert contract balance == 0. Correct holds, bug fails when withdrawAmount > 0.
        assertTrue(address(c).balance == 0);
    }
}

