pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address to, uint256 depositAmount) public {
        vm.assume(caller != address(0));
        vm.assume(to != address(0));
        vm.assume(caller != to);
        depositAmount = bound(depositAmount, 1, type(uint128).max);
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.deposit{value: depositAmount}();
        uint256 balanceBefore = address(c).balance;
        vm.prank(caller);
        try c.migrateTo(to) { } catch { }
        uint256 balanceAfter = address(c).balance;
        if (caller == c.creator()) {
            assertTrue(balanceAfter == 0);
        } else {
            assertTrue(balanceAfter == balanceBefore);
        }
    }
}
